"""English documentation. Section IDs match French for page-to-page switching."""
from html import escape
from textwrap import dedent
import re
from content.pages import PAGES as FRENCH, p
from content.downloads import downloads, VERSION


def code(text, language='shell'):
    return f'<div class="code-block"><div class="code-header"><span>{language}</span><button data-copy aria-label="Copy code" hidden>Copy</button></div><pre><code>{escape(dedent(text).strip())}</code></pre></div>'


def examples(slug, section):
    body = next(s['body'] for page in FRENCH if page['slug'] == slug for s in page['sections'] if s['id'] == section)
    return ''.join(re.findall(r'<div class="code-block">.*?</pre></div>', body, re.S)).replace('Copier le code', 'Copy code').replace('>Copier<', '>Copy<').replace('chemin/vers/', 'path/to/').replace('chemin/du/projet', 'path/to/project').replace('mon-api', 'my-api').replace('# Une fois MySQL prêt :', '# Once MySQL is ready:').replace('commandes de l’interface', 'workspace commands')


def table(headers, rows):
    head = ''.join(f'<th scope="col">{h}</th>' for h in headers)
    body = ''.join('<tr>' + ''.join(f'<td>{v}</td>' for v in row) + '</tr>' for row in rows)
    return f'<div class="table-wrap" role="region" aria-label="Table: {escape(headers[0], quote=True)}" tabindex="0"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'


# Slugs are translated by the builder; these stable keys identify matching pages.
PAGES = [
p('index', 'Documentation', 'Get started', 'Install Miblo, create a Rust API and manage its models from your terminal.', [
('comprendre', 'What Miblo generates', '<p>A Rust project with <strong>Axum</strong> for HTTP routes and <strong>SQLx</strong> for SQLite or MySQL. The source is yours to edit and runs with Cargo.</p>'),
('parcours', 'Get started', '<div class="doc-entry-list"><a href="installation.html"><span>01</span><div><strong>Install Miblo</strong><p>Requirements and installation commands.</p></div><b>→</b></a><a href="premiere-api.html"><span>02</span><div><strong>Create an API</strong><p>SQLite, a User model and a POST request.</p></div><b>→</b></a><a href="interface.html"><span>03</span><div><strong>Use the workspace</strong><p>Panels, shortcuts and status indicators.</p></div><b>→</b></a></div>'),
('capacites', 'Find an action', table(['Action', 'Guide'], [('Create a table and its CRUD routes', '<a href="modeles.html">Models and fields</a>'), ('Connect models', '<a href="relations.html">Relationships</a>'), ('Add a field', '<a href="migrations.html">Update a model</a>'), ('Add an endpoint', '<a href="routes.html">Routes</a>'), ('Send a request', '<a href="tester-les-routes.html">Test routes</a>'), ('Set up or migrate a database', '<a href="bases-de-donnees.html">SQLite and MySQL</a>'), ('Edit source code', '<a href="architecture.html">Generated code</a>'), ('Automate with scripts', '<a href="commandes.html">CLI reference</a>')])),
('version', 'Documented version', f'<p>CLI <strong>{VERSION}</strong>, templates <strong>0.6.0</strong>. Miblo generates Rust APIs. Node.js and OpenAPI generation are not available.</p><p>Miblo provides the structure. You implement business rules, authentication and deployment in the generated project. Miblo starts in English. Choose English or French with <kbd>Shift+L</kbd>; the preference is saved. These guides use the English menu labels. Generated comments and README files still follow the template pack’s language.</p>'),
]),
p('installation', 'Installation', 'Get started', 'Install Miblo for Rust API development on Windows, macOS or Linux. Rust, Cargo and rustfmt are required.', [
('prerequis', 'Prepare your environment', '<p>Install <strong>Rust 1.88 or later</strong>, Cargo and <code>rustfmt</code> through <a href="https://rustup.rs/">rustup</a>. The formatter is used when generating and merging Rust code.</p>' + examples('installation','prerequis') + table(['System','Native build tools'], [('macOS','Command Line Tools: <code>xcode-select --install</code>'),('Linux','A C/C++ compiler and linker, such as <code>build-essential</code> on Debian/Ubuntu.'),('Windows','Visual Studio Build Tools with “Desktop development with C++”, and the Rust MSVC toolchain.')]) + '<p>SQLite needs no database server. Python, Docker and <code>sqlx-cli</code> are not required to use Miblo.</p>'),
('installer', 'Install', code(f'cargo install miblo --version {VERSION} --locked\nmiblo --version') + '<p>This command installs or updates Miblo to the documented version. The first compilation can take several minutes. <code>--locked</code> keeps the tested dependency versions.</p><details class="doc-details"><summary>Install from a local checkout</summary>' + code('cargo install --path . --locked') + '</details>'),
('ouvrir', 'Launch Miblo', code('miblo') + '<p>This opens the terminal workspace in English by default. Press <kbd>Shift+L</kbd> to choose <strong>English</strong> or <strong>Français</strong>; your choice is saved. A project is opened automatically when the current directory contains <code>miblo.yaml</code>.</p>' + code('miblo ui --project path/to/my-api') + '<p>Without an interactive terminal, bare <code>miblo</code> prints help. <a href="commandes.html">CLI subcommands</a> are available for scripts.</p>'),
('distribution', 'Prebuilt binaries', downloads('en')),
('introuvable', 'Command not found', '<p>Open a new terminal and check that Cargo’s binary directory is in your <code>PATH</code>: usually <code>~/.cargo/bin</code> on Unix or <code>%USERPROFILE%\\.cargo\\bin</code> on Windows.</p><p>If linking fails, check your system’s native build tools. See <a href="depannage.html">troubleshooting</a> for other errors.</p>'),
]),
p('premiere-api', 'Build a Rust REST API with Axum and SQLite', 'Get started', 'Create a REST API with Rust, Axum and SQLite: generate a User model and CRUD routes, then test a POST request with Miblo.', [
('prerequis', 'Before you start', '<p>This tutorial creates a local API with a <code>users</code> table, five CRUD endpoints and a SQLite database. <strong>Miblo CLI</strong> generates editable Axum and SQLx source code.</p><p>You need <strong>Rust 1.88 or later</strong>, Cargo, rustfmt and your platform’s native build tools. <a href="installation.html#prerequis">Prepare your environment →</a> SQLite needs no database server or Docker. An Internet connection is needed for the first template and Rust dependency downloads.</p>' + code('rustup component add rustfmt\ncargo install miblo --version 0.9.1 --locked\nmiblo --version') + '<p>Scaffolding is quick; installation and the first Rust build can take several minutes. Use a new directory and an available port 3000.</p>'),
('projet','1. Create the project', code('miblo') + '<ol><li>Press <kbd>n</kbd> and enter <code>team-api</code>.</li><li>Choose a directory that does not exist yet, then port <code>3000</code>.</li><li>Select <strong>SQLite — local file, automatic setup</strong>.</li><li>Choose <strong>GitHub Releases</strong>, then <strong>Create project</strong>.</li></ol><p>Miblo creates the project and <code>miblo.sqlite</code>. The database status reads <strong>Migrations up to date</strong>.</p>'),
('modele','2. Add User','<ol><li>Press <kbd>a</kbd> and enter <code>User</code>.</li><li>Add <code>name</code>, type <strong>Short text (255 characters)</strong>, with no options.</li><li>Select <strong>Add another field</strong>: <code>email</code>, also short text. Toggle <strong>Unique</strong> with <kbd>Space</kbd>.</li><li>Select <strong>Finish and generate</strong>, accept <code>/users</code>, then <strong>Generate</strong>.</li></ol><p>Miblo creates the <code>users</code> table with an <code>id</code> primary key, Rust code and five CRUD routes. With the API stopped, the new SQLite model migration is applied automatically.</p>'),
('requete','3. Send a POST','<ol><li>Press <kbd>r</kbd> and wait for <strong>API running</strong>.</li><li>Use <kbd>Tab</kbd> to reach Routes, select <code>POST /users</code>, then press <kbd>x</kbd>.</li><li>The fields are prefilled. Press <kbd>Enter</kbd> to edit a value.</li><li>Select <strong>Send request</strong> and press <kbd>Enter</kbd>. The response is <strong>HTTP 201</strong>.</li><li>Test <code>GET /users</code> to retrieve the created row.</li></ol><p><kbd>s</kbd> stops the API. The first Rust build takes longer than subsequent starts.</p>'),
('commandes','The same steps in the shell', examples('premiere-api','commandes') + '<p>Open <code>miblo</code> in a second terminal inside <code>team-api</code> to test routes. An API started elsewhere is identified as external.</p>'),
('resultat', 'Generated routes and responses', table(['Method', 'Route', 'Result'], [('POST', '<code>/users</code>', 'Creates a user: HTTP 201 and its JSON.'), ('GET', '<code>/users</code>', 'Paginated list: HTTP 200 and a JSON array.'), ('GET', '<code>/users/{id}</code>', 'Reads a user: HTTP 200, or 404 if missing.'), ('PATCH', '<code>/users/{id}</code>', 'Updates the supplied fields: HTTP 200.'), ('DELETE', '<code>/users/{id}</code>', 'Deletes a user: HTTP 204, no response body.')]) + '<p>In a second terminal, create Alice with this command. Shell examples use macOS, Linux or Git Bash syntax; in PowerShell you can use <a href="tester-les-routes.html">Miblo’s request form</a>.</p>' + examples('premiere-api','resultat') + '<p>On a fresh database the first user gets ID <code>1</code>, with the HTTP 201 JSON shown above. Replace <code>1</code> with the returned ID if your database already contains rows. Repeating the POST with the same email returns <strong>409</strong> because the field is unique. Keep the API running in the first terminal; <kbd>Ctrl+C</kbd> stops it.</p>'),
('fichiers', 'Where to edit the generated code', examples('premiere-api','fichiers').replace('arborescence simplifiée','simplified project tree') + '<p><code>handlers.rs</code> handles HTTP, <code>service.rs</code> holds your business rules and <code>repository.rs</code> contains SQL queries. <code>requests.rs</code> describes request data. <a href="architecture.html">Explore the full architecture →</a></p><p>To start with MySQL, use <code>--database mysql</code> in a new project and configure an existing server: <a href="bases-de-donnees.html#mysql">MySQL setup</a>. This does not convert an existing SQLite database.</p>'),
('suite','Continue building','<p>Continue with the <a href="exemple-equipes.html">User and Group example: a foreign key and a custom route</a>.</p><p>Press <kbd>m</kbd> to <a href="migrations.html">add a field</a>, <kbd>g</kbd> to <a href="routes.html">create a route</a>, <kbd>d</kbd> to <a href="relations.html#schema">inspect the schema</a>, or <kbd>e</kbd> to open the code.</p>'),
]),
p('interface','Terminal interface and shortcuts','Build','Navigate Miblo’s terminal workspace, manage your API and read its status indicators.',[
('navigation','Navigate',table(['Key','Action'],[('↑ / ↓ or j / k','Move the selection.'),('Tab / Shift+Tab','Switch panels.'),('Enter','Confirm or open the selection.'),('Escape','Close a dialog or cancel input.'),('Space','Open Actions; toggle a form option.'),('?','Open help.')]) + '<p>Panels display models, files, routes, HTTP responses and logs. <kbd>d</kbd> switches from routes to the schema. <kbd>v</kbd> hides the compact code preview.</p><p>Minimum terminal size: <strong>70 × 20</strong>. The code preview hides automatically below 30 rows.</p>'),
('raccourcis','Main actions',table(['Key','Action'],[('n / o','Create / open an API'),('a','Add model, table and CRUD'),('m','Add fields or relationships to an existing model'),('g','Create a route'),('r / s','Start / stop the API'),('b','Configure, initialize or migrate the database'),('d / p','Show schema / switch its source'),('x / Enter','Test the selected route'),('f','Custom HTTP request'),('e','Open code in your editor'),('c','Run cargo check'),('u','Update templates for future additions'),('t / F5','Change theme / refresh'),('Shift+L','Choose English or French and save the preference'),('q','Quit')])),
('langue', 'Choose Miblo’s language', '<p>Since 0.9.1, Miblo starts in <strong>English</strong>, regardless of your system language.</p><ol><li>Press <kbd>Shift+L</kbd> (uppercase L), or open <kbd>Space</kbd> → <strong>Language / Langue</strong>.</li><li>Choose <strong>English</strong> or <strong>Français</strong> with the arrows, then press <kbd>Enter</kbd>.</li></ol><p><code>:language</code> and <code>:langue</code> open the same menu. The change is immediate and saved for the next launch. Your project stays open and the API keeps running.</p><p>Menus, forms, help and status panels use the selected language. Generated files, SQL data and existing logs keep their content. Command names and <code>--help</code> remain in English; generated comments and README files follow the template pack’s language.</p><p>The website’s EN / FR switch only changes the documentation. Use the application menu to change Miblo. <a href="configuration.html#preferences">Preferences and language overrides →</a></p>'),
('commandes','Command bar','<p>Press <kbd>:</kbd> to enter a workspace command:</p>' + examples('interface','commandes') + '<p>Workspace commands are not all CLI subcommands. Use the <a href="commandes.html">CLI reference</a> for scripts.</p>'),
('etats','Read status indicators',table(['Color','API','Database'],[('Green','HTTP health check responds.','Connected; migrations up to date.'),('Orange','Starting or restart required.','Initialization or pending migrations.'),('Red','Process or response error.','Connection failed or inconsistent migration.'),('Gray','Stopped or no project.','Check pending or no database.')]) + '<p>Status refreshes about every three seconds. Miblo identifies an externally started API and does not stop that process.</p>'),
('editeur','Editor, animation and exit','<p><kbd>e</kbd> uses <code>VISUAL</code>, then <code>EDITOR</code>, then vi on Unix or notepad on Windows. Arguments such as <code>EDITOR="code --wait"</code> are supported. Miblo restores the terminal while you edit.</p><p>Any key skips the blue startup animation; set <code>MIBLO_NO_ANIMATION=1</code> to disable it. Three session themes are available.</p><p>Normal exit stops the processes Miblo started. Finish generation, compilation and HTTP jobs first: exit is blocked while those jobs are running.</p>'),
]),
p('modeles','Models and fields','Build','Generate a SQL table, Rust model and five CRUD endpoints from a model definition.',[
('ajouter','Create a model','<ol><li>Press <kbd>a</kbd> and name the model, for example <code>User</code>.</li><li>Name a field, choose its type and toggle options with <kbd>Space</kbd>.</li><li>Add fields or a relationship from <strong>Model fields</strong>.</li><li>Select <strong>Finish and generate</strong>, confirm the collection path, then <strong>Generate</strong>.</li></ol><p><code>id</code> is added automatically. Use field names such as <code>first_name</code>. Escape cancels before generation.</p>' + examples('modeles','ajouter') + '<p><code>--path /members</code> changes the collection path. Without fields or <code>--yes</code>, the CLI starts its wizard.</p>'),
('types','Field types',table(['Type','Rust','SQLite','MySQL'],[('string','String','TEXT','VARCHAR(255)'),('text','String','TEXT','TEXT'),('int','i64','INTEGER','BIGINT'),('float','f64','REAL','DOUBLE'),('bool','bool','INTEGER','BOOLEAN')]) + '<p>Optional fields use <code>Option&lt;T&gt;</code>. Syntax: <code>name:type?:option</code>, for example <code>description:text?</code>.</p>'),
('options','Options and private fields',table(['Option','Example','Behavior'],[('Optional','<code>nickname:string?</code>','Accepts NULL.'),('Unique','<code>email:string:unique</code>','Adds a unique constraint. Use string, rather than text, for unique text.'),('Private','<code>token:string:private</code>','Accepts writes; omits the value from CRUD responses.')]) + '<p>Common sensitive names (password, password_hash, secret, token, api_key) become private through the CLI. This filtering does not encrypt data or add authentication.</p>'),
('crud','Generated CRUD',table(['Method','User path','Result'],[('GET','/users','Paginated list: limit and offset, at most 100 rows per page.'),('POST','/users','Create: 201.'),('GET','/users/{id}','Row or 404.'),('PATCH','/users/{id}','Update supplied fields; omitted fields remain unchanged.'),('DELETE','/users/{id}','Delete: 204; missing row: 404.')]) + '<p>Unknown fields and invalid types are rejected. Unique conflicts return 409. Empty PATCH requests, changing id and NULL for required fields are rejected.</p>'),
('preservation','Keep existing project changes','<p>Adding a model writes its files and migration without regenerating existing resources. Registries, <code>miblo.yaml</code> and <code>.miblo/state.json</code> are updated.</p><p><code>--dry-run</code> previews the plan. File collisions or managed registry conflicts stop the operation. Use <a href="migrations.html">miblo edit or m</a> to add a field.</p>'),
]),
p('relations','Relationships and foreign keys','Build','Connect Rust API models with SQL foreign keys, indexes and deletion rules.',[
('creer','User.group_id → Group.id','<ol><li>Create <code>Group</code> with a <code>name</code> field.</li><li>Add <code>User</code> with <kbd>a</kbd>. After its fields, select <strong>Add a relationship (foreign key)</strong> (add a foreign key).</li><li>Select <strong>Group → groups.id</strong> and accept <code>group_id</code>.</li><li>Choose options and a deletion rule.</li><li>Finish and confirm generation.</li></ol><p>Miblo generates an integer field, index and SQL constraint. For an existing User, use <kbd>m</kbd> → <strong>Add an optional relationship</strong> (add an optional relationship).</p>' + examples('relations','creer')),
('regles','Choose a deletion rule',table(['Rule','Effect on related rows'],[('RESTRICT (default)','Prevents deleting a referenced row.'),('CASCADE','Also deletes rows that reference it.'),('SET NULL','Keeps related rows and clears the reference; requires an optional field.')]) + examples('relations','regles')),
('formes','Unique references and self-references','<p><code>:unique</code> allows each non-NULL referenced value in only one row. Self-references are supported:</p>' + examples('relations','formes') + '<p>CRUD exposes IDs, without automatic joins or nested objects. Custom or composite primary keys and automatic many-to-many tables are not generated.</p>'),
('schema','Inspect the schema','<ol><li>Press <kbd>d</kbd> to open the actual database schema.</li><li>Select a table to see columns, primary and foreign keys, and deletion rules.</li><li><kbd>p</kbd> switches to declared models. <kbd>F5</kbd> refreshes; <kbd>d</kbd> returns to routes.</li></ol><p>Manually created tables are visible too. Internal SQLite and SQLx tables are hidden. This view shows structure; test routes to read rows.</p>' + examples('relations','schema')),
]),
p('migrations','Update models and migrations','Build','Add optional fields or relationships to existing tables while keeping their rows.',[
('modifier','Add a field','<ol><li>Stop the API with <kbd>s</kbd>, then press <kbd>m</kbd>.</li><li>Choose the model and <strong>Add an optional field</strong> (add optional field).</li><li>Enter <code>nickname</code>, choose <strong>Short text (255 characters)</strong>, then confirm the options.</li><li>Select <strong>Finish and generate</strong>, review the SQL and confirm.</li></ol><p>Miblo generates an <code>ALTER TABLE</code> migration and Rust changes. Existing rows receive <code>NULL</code> when the migration is applied.</p>' + examples('migrations','modifier') + '<p>For a relationship, choose <strong>Add an optional relationship</strong> and the target model. <a href="relations.html#regles">Deletion rules</a> apply here too.</p>'),
('appliquer','Apply the migration','<ol><li>The database status becomes <strong>Database update required</strong> (database update required).</li><li>Press <kbd>b</kbd> → <strong>Apply migrations</strong> (apply migrations), then confirm.</li><li>Wait for <strong>Migrations up to date</strong>, then start with <kbd>r</kbd>.</li></ol><p>Editing a model does not automatically apply its migration, including with SQLite. Starting the generated API also applies pending migrations.</p>' + examples('migrations','appliquer') + '<p>Keep already applied migration files unchanged.</p>'),
('fusion','Your code changes','<p>Miblo merges generated code with your edits. A conflict stops the operation before writing. Existing handlers and services in the current architecture remain unchanged when adding a field.</p><p>Replaced files are copied to <code>.miblo/backups/</code>. These are source and metadata backups, not database backups.</p>'),
('limites','Supported changes',table(['Automated','Implement in your project'],[('Add an optional field, possibly unique.','Rename, remove or change a column type.'),('Add an optional relationship.','Change an existing relationship or make a field required.')]) + '<p>Additions preserve existing rows. Miblo does not choose backfill values for them.</p>'),
]),
p('routes','Create API routes','Build','Connect a new HTTP endpoint to a model’s SQL-backed CRUD, or generate a custom handler and service.',[
('modele','Create POST /members for User','<ol><li>Press <kbd>g</kbd> and select <strong>User</strong>.</li><li>Choose <strong>Create a row</strong> (create a row). POST is selected automatically.</li><li>Enter <code>/members</code>, then accept or change the proposed function name.</li><li>Confirm <strong>Create files</strong> (create files).</li><li>Restart with <kbd>s</kbd>, then <kbd>r</kbd>, to load the route.</li></ol><p>This endpoint uses User’s existing CRUD and SQL queries. It writes to <code>users</code>; it does not create another table.</p>' + examples('routes','modele')),
('actions','Available actions',table(['CLI action','Method','Example path'],[('list','GET','/members'),('get','GET','/members/{id}'),('create','POST','/members'),('update','PATCH','/members/{id}'),('delete','DELETE','/members/{id}')]) + '<p>Single-row actions require exactly one {id} parameter. List and create accept none. Different methods can share a path with distinct module names.</p>' + examples('routes','actions') + '<p>A list action at /users/active still returns a paginated list. Naming a path does not implement a filter or permission rule.</p>'),
('personnalisee','Generate a function to implement','<p>In <kbd>g</kbd>, select <strong>Custom logic — no model</strong> (custom logic without a model), or a model followed by <strong>Custom logic — to implement (501)</strong>. Choose method, path, function name and optional request body.</p>' + examples('routes','personnalisee') + '<p><code>handlers.rs</code>, <code>requests.rs</code> and <code>service.rs</code> are created in <code>src/resources/custom_routes/activate_user/</code>. The route returns <strong>501</strong> until its business function is implemented.</p><p>Select the route and press <kbd>e</kbd>. The function receives the SQL pool, path parameters, query parameters and optional JSON. Adapt the types, implement the behavior, then restart.</p>'),
('compatibilite','Templates, paths and conflicts','<p>Model actions require template pack <strong>0.6.0</strong>. In older projects, use <kbd>u</kbd> → GitHub Releases, or <code>miblo template update</code>. Existing models keep their architecture.</p><p>Paths use /segments/{parameters}, without query strings or wildcards. Duplicate method/path pairs and known CRUD or /health collisions are rejected. GET reserves HEAD. Check routes registered outside Miblo yourself.</p><p><code>--dry-run</code> previews the plan; <code>--offline</code> uses cached templates.</p>'),
]),
p('tester-les-routes','Test HTTP routes','Build','Send POST and PATCH requests with prefilled forms, and inspect HTTP responses inside Miblo.',[
('post','Send a POST','<ol><li>Start the API with <kbd>r</kbd>. Select a POST route and press <kbd>x</kbd>.</li><li><strong>Prepare request</strong> shows the model fields.</li><li>Use arrows to choose a value and <kbd>Enter</kbd> to edit it.</li><li>Select <strong>Send request</strong> and press <kbd>Enter</kbd>.</li></ol><p>You do not write JSON. Optional fields start at <code>NULL</code>, private values are masked and <code>id</code> is excluded. Unique example values change for each new request draft.</p>'),
('patch','Update with PATCH',table(['Form key','Effect'],[('Enter','Edit the selected value.'),('Space','Include or exclude a field.'),('n','Set an optional field to NULL.'),('Home','Return to Send request.'),('Escape','Close input or cancel the request.')]) + '<p>PATCH fields start excluded and retain their database values. Include only the fields you want to change. Empty PATCH requests are rejected.</p>'),
('references','Choose an existing reference','<p>Foreign keys offer up to 20 rows fetched through the target model’s collection endpoint. A required reference is preselected when a row is available.</p><p>Otherwise create the target row first or enter an existing ID. The tester never creates a related row automatically. Optional references can stay NULL.</p>'),
('libres','Custom requests and forms','<p><kbd>f</kbd> opens a custom request: GET, POST, PATCH, PUT, DELETE, HEAD or OPTIONS. Known CRUD paths receive their model fields. <kbd>+</kbd> adds a text, integer, decimal or boolean field; Delete removes it.</p><p>For custom routes associated with a model, fields are editable suggestions, not an inferred request contract. Form edits do not change your models.</p><p>Nested payloads, inference from handwritten Rust types and custom authentication headers are not supported yet. Use an external HTTP client for those cases.</p>'),
('resultats','Read the response','<p>Miblo shows HTTP status, elapsed time and a formatted response. Timeout: 10 seconds; displayed body: 64 KiB; redirects are not followed.</p><p>No write request is sent before you explicitly choose Send. Bodyless DELETE requests ask for confirmation. Escape goes back or cancels.</p>' + table(['Status','Meaning'],[('200 / 201 / 204','Read or update / created / deleted without content.'),('400 / 422','Check values, JSON shape or types; 400 for a missing referenced row.'),('404','Route or row not found.'),('409','Unique constraint conflict (for example, an email already in use).'),('501','Custom function needs implementation.') ])),
]),
p('bases-de-donnees','SQLite and MySQL','Reference','Configure SQLite automatically or connect Miblo to MySQL, then inspect and apply SQL migrations.',[
('sqlite','SQLite','<p>Choose SQLite when creating a project. Miblo prepares <code>.env</code>, creates <code>miblo.sqlite</code> and applies initial migrations. No database server is needed.</p>' + table(['Miblo operation','SQLite migration'],[('Create project','Applied automatically.'),('Add model with API stopped','Applied automatically.'),('Edit model with m','Apply with b or on the next API start.')]) + examples('bases-de-donnees','sqlite') + '<p>The generated API also creates a missing database file and applies migrations at startup.</p>'),
('mysql','MySQL','<ol><li>Start a MySQL server, then choose MySQL when creating the project.</li><li>Enter host, port, database, username and password in Miblo.</li><li>Confirm <strong>Save the MySQL connection?</strong>. It is written to <code>.env</code>.</li><li>In <kbd>b</kbd>, select <strong>Initialize the database and tables</strong>, then confirm.</li></ol><p>The MySQL account needs permission for the requested operation. Miblo does not start a MySQL server.</p><details class="doc-details"><summary>Use the included compose.yaml</summary><p>For local development, use the generated MySQL service and connection values from <code>.env.example</code>.</p>' + examples('bases-de-donnees','mysql') + '</details>'),
('commandes','Database commands',table(['Command','Effect'],[('<code>miblo db check</code>','Test the connection.'),('<code>miblo db init</code>','Initialize if needed and apply migrations.'),('<code>miblo db migrate</code>','Apply pending migrations.'),('<code>miblo db schema</code>','Print the actual schema as JSON.')]) + '<p><code>--project PATH</code> selects a project in another directory. Passwords are not passed as command arguments.</p>'),
('connexion','Configuration and limits','<p>Miblo’s database commands read DATABASE_URL from the project’s .env first, falling back to the environment if absent. The generated API uses its runtime configuration; avoid conflicting file and shell values.</p><p>The database engine is selected at creation. Switching engines requires a separate code and data migration. The <a href="relations.html#schema">schema view</a> distinguishes the actual database from declared models.</p>'),
]),
p('architecture','Generated Rust code','Reference','Find your Axum handlers, request types, business logic and SQLx queries in the generated project.',[
('arborescence','One directory per resource',code('''src/
├── main.rs                  # Server startup
├── lib.rs                   # Shared state and route assembly
├── config.rs                # Environment configuration
├── database.rs              # SQL pool and migrations
├── error.rs                 # Error responses
├── patch.rs                 # Omitted / NULL / value
└── resources/
    ├── mod.rs               # Registry managed by Miblo
    └── user/
        ├── mod.rs           # User routes
        ├── handlers.rs      # HTTP extraction and responses
        ├── model.rs         # Data structures
        ├── requests.rs      # Request types and validation
        ├── service.rs       # Business rules
        └── repository.rs    # SQL and transactions''','project tree') + '<p>SQL migrations live in migrations/. Additional routes live in src/resources/custom_routes/. The generated French README explains configuration, files and requests.</p>'),
('modifier','Where to write your logic',table(['Change','File'],[('Business rule','<code>service.rs</code>'),('Request validation','<code>requests.rs</code>'),('SQL query','<code>repository.rs</code>'),('HTTP extraction and response','<code>handlers.rs</code>'),('Manually registered routes','<code>src/lib.rs</code>, outside managed registries')]) + '<p>A write follows <strong>handler → service → repository</strong>. Code is formatted with rustfmt and includes focused comments.</p>'),
('autonomie','An independent project',code('cargo check\ncargo test\ncargo run') + '<p>The API runs without Miblo. SQLx queries run at runtime: building does not need a live database or .sqlx directory. A lockfile pins dependencies.</p><p>The scaffold includes health, PATCH deserialization and request-validation tests in the current architecture. Add tests for your own business logic.</p>'),
('registres','Files managed by Miblo','<p>Commit miblo.yaml and .miblo/state.json alongside your source. They retain definitions, pinned templates and merge baselines.</p><p>src/resources/mod.rs and custom_routes/mod.rs are managed registries. Business code there can block additions. Customize resource files or route assembly in src/lib.rs.</p>'),
]),
p('templates','Templates and offline mode','Reference','Download versioned Miblo templates, verify their checksums and reuse them offline.',[
('distribution','Available packs','<p>New projects use format 3 and template packs <strong>0.6.0</strong>. The CLI also reads formats 1 and 2.</p>' + table(['Database','Pack'],[('SQLite','<a href="https://github.com/NaSuRall/miblo_templates/releases/download/v0.6.0/rust-axum-sqlite.tar.gz">rust-axum-sqlite.tar.gz</a>'),('MySQL','<a href="https://github.com/NaSuRall/miblo_templates/releases/download/v0.6.0/rust-axum-mysql.tar.gz">rust-axum-mysql.tar.gz</a>')]) + '<p>Each archive has a .sha256 sidecar. Projects pin the version, URL, digest and fingerprint. Templates are downloaded separately, not embedded in the binary.</p>'),
('cache','Use the cache',examples('templates','cache') + '<p>Offline mode requires previously downloaded templates. <code>--cache-dir</code> or <code>MIBLO_CACHE_DIR</code> selects the cache directory; otherwise XDG_CACHE_HOME, LOCALAPPDATA or ~/.cache/miblo is used.</p><p>The template cache is separate from Cargo’s cache. Offline compilation also requires the Rust dependencies.</p>'),
('mise-a-jour','Update templates','<p>Press <kbd>u</kbd>, choose GitHub Releases, a local directory or a URL, then confirm <strong>Update</strong> (update).</p>' + examples('templates','mise-a-jour') + '<p>The new pack is used for future models and routes. Existing models retain their pinned templates, source files and migrations.</p>'),
('personnaliser','Host or develop a pack',examples('templates','personnaliser') + '<p>Replace example URLs with your server. A base URL is followed by /v0.6.0/&lt;stack&gt;.tar.gz. <code>--sha256 HEX</code> supplies a known digest. HTTPS is required except for loopback testing.</p><p>A local pack contains manifest.json and Handlebars files. Keep it available and unchanged. Releases avoid maintaining a local template directory.</p>'),
('integrite','Download verification','<p>Miblo verifies SHA-256 and rejects corrupt archives, links, unexpected files and paths escaping the extraction directory. A new version requires a new archive.</p><p>A checksum verifies downloaded content; it is not a publisher signature.</p>'),
]),
p('commandes','CLI command reference','Reference','Miblo commands and options for project creation, models, routes, databases and templates.',[
('global','Help and main commands',examples('commandes','global') + table(['Command','Purpose'],[('<code>miblo</code>','Open the workspace in an interactive terminal.'),('<code>miblo ui --project PATH</code>','Open a project.'),('<code>miblo new [NAME]</code>','Create an API.'),('<code>miblo add [NAME] [FIELD]...</code>','Add a model.'),('<code>miblo edit NAME [FIELD]...</code>','Add optional fields.'),('<code>miblo route add NAME --path PATH</code>','Create a route.'),('<code>miblo run --project PATH</code>','Run cargo run.'),('<code>miblo doctor --project PATH</code>','Check metadata, registries and prerequisites.'),('<code>miblo db ACTION --project PATH</code>','check, init, migrate or schema.'),('<code>miblo template update</code>','Update templates for future additions.')])),
('new','Create: miblo new',examples('commandes','new') + table(['Option','Purpose'],[('<code>--output PATH</code>','Destination; an existing directory is refused.'),('<code>--database sqlite|mysql</code>','SQLite by default interactively; MySQL with --yes and no explicit engine.'),('<code>--port PORT</code>','Default: 3000.'),('<code>--resource NAME</code> / <code>--field FIELD</code>','Initial model and repeated fields.'),('<code>--config PATH</code>','Version 1 YAML definition.'),('<code>--template-dir PATH</code>','Local pack; incompatible with direct URL/digest options.'),('<code>--template-url URL</code>','Direct archive URL.'),('<code>--template-base-url URL</code>','Distribution server.'),('<code>--template-version VERSION</code>','Pack version.'),('<code>--sha256 HEX</code>','Known digest without fetching a sidecar.'),('<code>--yes</code> / <code>--dry-run</code>','Accept choices / preview without writing the project.'),('<code>--offline</code> / <code>--cache-dir PATH</code>','Template cache options.')])),
('add-edit','Add and update models',examples('commandes','add-edit') + '<p>Supply fields positionally or with repeated --field options, never both. The legacy <code>miblo add resource User --field name:string --yes</code> syntax is still accepted.</p><p>Shared options: --project, --yes, --dry-run, --offline, --cache-dir. add also accepts --path. edit requires optional fields and an existing model.</p>'),
('route','Create a route',examples('commandes','route') + '<p>--action list|get|create|update|delete requires --resource and determines the method. Without an action, --method and --json-body describe a custom stub. Other options: --project, --yes, --dry-run, --offline, --cache-dir.</p>'),
('templates','Update templates',examples('commandes','templates') + '<p>Options: --template-dir or --template-url, --template-version, --template-base-url, --project, --dry-run, --offline and --cache-dir. Check --help for your installed version before automating a new workflow.</p>'),
]),
p('configuration','Configuration','Reference','Project files and environment variables used by Miblo and your generated Rust API.',[
('fichiers','Important files',table(['File','Purpose'],[('<code>miblo.yaml</code>','Version 1 project, model, field and route definition.'),('<code>.miblo/state.json</code>','Pinned packs, fingerprints and merge baselines.'),('<code>.miblo/backups/</code>','Source backups created during model changes.'),('<code>.env</code>','Private runtime configuration.'),('<code>.env.example</code>','Shareable example.'),('<code>migrations/</code>','Versioned SQL history.'),('<code>Cargo.lock</code>','Dependency versions.')]) + '<p>Commit source, migrations, miblo.yaml and .miblo/state.json. Private .env files are hidden in the explorer; .env.example remains visible.</p>'),
('variables','Environment variables',table(['Variable','Purpose'],[('<code>DATABASE_URL</code>','API connection; database-command fallback when absent from .env.'),('<code>SERVER_ADDRESS</code> / <code>SERVER_PORT</code>','Server listener; refresh after changes.'),('<code>MIBLO_TEMPLATE_DIR</code>','Local development pack.'),('<code>MIBLO_TEMPLATE_BASE_URL</code>','Template distribution server.'),('<code>MIBLO_CACHE_DIR</code>','Template cache.'),('<code>MIBLO_LANGUAGE</code>','en or fr: language override at startup.'),('<code>MIBLO_CONFIG_DIR</code>','User preferences directory.'),('<code>VISUAL</code> / <code>EDITOR</code>','Editor and arguments.'),('<code>MIBLO_NO_ANIMATION</code>','Disables startup animation when set.')]) + '<p>For the address monitored by the workspace, environment values take priority over .env and project defaults. Wildcard bind addresses are checked through loopback. Avoid conflicting values.</p>'),
('preferences', 'User preferences', '<p>The language choice is saved in <code>settings.json</code>, outside your API projects:</p><ul><li>macOS: <code>~/Library/Application Support/miblo/settings.json</code></li><li>Linux: <code>$XDG_CONFIG_HOME/miblo/settings.json</code>, or <code>~/.config/miblo/settings.json</code></li><li>Windows: <code>%APPDATA%\\miblo\\settings.json</code></li></ul><p><code>XDG_CONFIG_HOME</code> also takes precedence on macOS. <code>MIBLO_CONFIG_DIR</code> overrides this directory on all platforms.</p><p>At startup, <code>MIBLO_LANGUAGE=en</code> or <code>MIBLO_LANGUAGE=fr</code> overrides the saved preference. Without either, Miblo uses English. You can still switch from the menu during the session.</p><p>If saving fails, Miblo reports it and applies the choice for the current session. An invalid preferences file does not prevent startup and is not overwritten.</p>'),
('definitions','Create from a definition','<p>A YAML file can describe a new project:</p>' + examples('configuration','definitions') + '<p>The destination directory must not exist. Editing this file in an existing project does not migrate its database: use <a href="migrations.html">miblo edit</a> to add fields.</p>'),
('compatibilite','Project versions',table(['Format','Version'],[('miblo.yaml definition','schema_version: 1'),('Current templates','Pack 0.6.0, format 3'),('Template formats read by the CLI','1, 2 and 3')]) + '<p>A project can contain models from different packs. Legacy config.yaml files are not converted automatically. Engine changes, renames and removals require manual migrations.</p>'),
]),
p('depannage','Troubleshooting','Help and contribute','Resolve template errors, route responses, database status and Rust build problems in Miblo.',[
('doctor','Run diagnostics',examples('depannage','doctor') + '<p><code>doctor</code> checks project metadata and prerequisites. <code>db check</code> tests the connection. Read Logs for the full error.</p>'),
('template-404','Unavailable template or 404','<p>Check the version, source and access to <a href="https://github.com/NaSuRall/miblo_templates/releases">template releases</a>. Custom URLs need both the archive and its .sha256 sidecar.</p><p>The workspace lets you change source or retry while keeping the name, destination and port. A failed download does not create the project.</p>'),
('template-change','Template changed since project creation','<p>The pinned local pack changed or is missing. Restore its exact content for models that depend on it. For future additions, select a published pack with u or:</p>' + examples('depannage','template-change') + '<p>This does not rewrite existing models or migration history. Do not delete metadata to bypass the check.</p>'),
('route-501','A route returns 501','<p>The route uses <strong>Custom logic</strong>. Select it, press <kbd>e</kbd>, implement <code>service.rs</code>, then restart.</p><p>To reuse a model’s SQL directly, create a route with that model <strong>and a CRUD action</strong>: list, get, create, update or delete.</p>'),
('bdd-orange','Orange or red database status',table(['Displayed status','Action'],[('Database update required','Stop the API, then b → Apply migrations.'),('Database needs initialization','b → Initialize the database and tables.'),('Database unavailable','Check the connection; for MySQL, check the server and credentials.'),('Migration mismatch','Restore the applied migration, then write a new migration for the change.') ])),
('conflits','Conflicts or interrupted operations','<p>Existing files, modified registries or incompatible code changes can stop generation. Resolve the reported files before retrying. Place manual route registration in src/lib.rs.</p><p>An interruption may leave .miblo/operation.lock and partial writes. Check that no operation is running, inspect the diff, restore a consistent state, then remove the stale lock. Multi-file writes are not an atomic transaction.</p>'),
('langue', 'Language changes after restarting', '<p>Choose a language with <kbd>Shift+L</kbd>, then press <kbd>Enter</kbd>. If your shell defines <code>MIBLO_LANGUAGE</code>, it takes precedence at the next launch: unset it to use the saved choice.</p><p>If Miblo cannot save the preference, check the permissions of the <a href="configuration.html#preferences">preferences directory</a> and the validity of <code>settings.json</code>. The current session remains usable.</p>'),
('compiler','Build failures, busy ports or missing commands','<p>Install rustfmt with <code>rustup component add rustfmt</code>. For linker errors, check C/C++ tools. For an occupied port, change SERVER_PORT, refresh with F5 and restart.</p><p>Check Cargo’s PATH if the command is missing. Bug reports should include version, OS, command and error, without private .env content.</p>'),
]),
p('contribuer','Contribute','Help and contribute','Contribute to Miblo’s open-source CLI, templates and documentation on GitHub.',[
('depots','Repositories','<ul><li><a href="https://github.com/NaSuRall/Miblo">Miblo</a>: CLI, terminal UI, generation and project management.</li><li><a href="https://github.com/NaSuRall/miblo_templates">miblo_templates</a>: Handlebars packs and published archives.</li><li><a href="https://github.com/NaSuRall/miblo_site">miblo_site</a>: this website and documentation.</li></ul><p>Report bugs, suggest improvements or contribute source changes on GitHub. Miblo uses the MIT license.</p>'),
('checks','Check the CLI',examples('contribuer','checks') + '<p>Repository scripts also cover installation, generation, migrations, SQLite/MySQL CRUD and the terminal UI. Test dependencies are listed in <code>scripts/requirements-test.txt</code>.</p>'),
('templates','Test a generated API','<p>With CLI and template repositories in adjacent directories:</p>' + examples('contribuer','templates') + '<p>These tests use temporary projects and data. See the development branch README for MySQL, terminal and installation checks and their dependencies.</p>'),
('beta','Before a release','<p>Check installation, generation from published templates, migrations and preservation of handwritten changes. The automated terminal test runs on Unix; also check the Windows terminal.</p><p>The CLI, templates and website are published separately. Each repository describes its checks.</p>'),
]),
]
